#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
#pragma omp parallel
    {
#pragma omp single
        max_threads = omp_get_num_threads();
    }

    std::vector<double> block_sums(static_cast<std::size_t>(max_threads), 0.0);

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const std::size_t start = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(nt);
        const std::size_t end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(nt);

        double running = 0.0;
        for (std::size_t i = start; i < end; ++i) {
            running += x[i];
            output[i] = running; // only this thread writes its own [start, end) range
        }

        block_sums[static_cast<std::size_t>(tid)] = running;

#pragma omp barrier

        double offset = 0.0;
        for (int t = 0; t < tid; ++t) {
            offset += block_sums[static_cast<std::size_t>(t)];
        }

        if (offset != 0.0) {
            for (std::size_t i = start; i < end; ++i) {
                output[i] += offset; // only this thread writes its own [start, end) range
            }
        }
    }
}
